(function(root){
  'use strict';
  const D=root.InstagramArchiveData;
  let profile='seulgi',view='feed',postId='',slide=0,returnView='feed',followingOpen=false,feedSlides={},query='';
  const activityKey='pocket-story-instagram-activity-v1';
  let activity={likes:{},comments:{}};
  try{const saved=JSON.parse(localStorage.getItem(activityKey));if(saved&&typeof saved==='object')activity={likes:saved.likes||{},comments:saved.comments||{}}}catch{}
  const persist=()=>{try{localStorage.setItem(activityKey,JSON.stringify(activity))}catch{}};
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date=p=>p.date.replaceAll('-','.');
  const find=id=>D.posts.find(p=>p.id===id);
  const by={handle:'by.sseulgi',name:'by.sseulgi',url:'https://www.instagram.com/by.sseulgi/',color:'#818c93',initial:'by'};
  const account=p=>p.account==='by.sseulgi'?'by':p.owner;
  const person=key=>key==='by'?by:D.profiles[key];
  const own=()=>D.posts.filter(p=>account(p)===profile).sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
  const feed=()=>D.posts.filter(p=>p.owner==='seulgi').sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
  const photo=img=>img?.source?.startsWith('https://img-cdn.theqoo.net/')?'instagram/'+img.source.split('/').pop().split('?')[0]:'';
  const images=p=>p.images.filter(img=>photo(img));
  const avatar=p=>`<span class="ig2-avatar" style="--ig-color:${p.color}">${p.initial||esc(p.name[0])}</span>`;
  const label=p=>esc(p.handle);
  function header(title,back=false){return `<header class="ig2-header"><button ${back?'data-ig-back':'data-nav="phonehome"'} aria-label="返回">‹</button><strong>${esc(title)}</strong><button data-nav="phonehome" aria-label="返回桌面">⌂</button></header>`}
  function bottom(){return `<nav class="ig2-bottom"><button data-ig-view="feed" class="${view==='feed'?'selected':''}" aria-label="动态首页"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/></svg></button><button data-ig-view="search" class="${view==='search'?'selected':''}" aria-label="搜索"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/></svg></button><button data-ig-view="activity" class="${view==='activity'?'selected':''}" aria-label="你的动态"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 21s-9-5.5-9-11.4C3 3.7 9 2.5 12 7c3-4.5 9-3.3 9 2.6C21 15.5 12 21 12 21Z"/></svg></button><button data-ig-view="profile" class="${view==='profile'?'selected':''}" aria-label="涩琪主页">${avatar(D.profiles.seulgi)}</button></nav>`}
  function tile(p){const pics=images(p),img=pics[0];return `<button class="ig2-tile ${img?'':'ig2-text-tile'}" data-ig-post="${esc(p.id)}" aria-label="打开 ${date(p)} ${esc(p.title)}">${img?`<img src="${esc(photo(img))}" alt="${esc(img.alt)}" loading="lazy">`:`<span>${esc(p.title)}</span>`}${pics.length>1?'<b aria-hidden="true">▣</b>':''}</button>`}
  function following(){const rows=[['irene','IRENE','renebaebae'],['wendy','WENDY','todayis_wendy'],['joy','JOY','_imyour_joy'],['yeri','YERI','yerimiese'],['by','by.sseulgi','by.sseulgi']];return `<section class="ig2-following"><header><button data-ig-following aria-label="关闭关注列表">‹</button><strong>팔로잉</strong><span>5</span></header>${rows.map(([key,name,handle])=>key==='irene'||key==='by'?`<button class="ig2-follow-row" data-ig-profile="${key}">${avatar(person(key))}<span><strong>${esc(handle)}</strong><small>${esc(name)}</small></span><b>›</b></button>`:`<a class="ig2-follow-row" href="https://www.instagram.com/${handle}/" target="_blank" rel="noopener noreferrer"><span class="ig2-avatar ig2-initial">${name[0]}</span><span><strong>${esc(handle)}</strong><small>${esc(name)}</small></span><b>↗</b></a>`).join('')}</section>`}
  function profilePage(){const p=person(profile),posts=own();return `${header(p.handle)}<div class="nf-scroll ig2-scroll"><section class="ig2-profile"><div class="ig2-profile-top">${avatar(p)}<div class="ig2-stat"><strong>${posts.length}</strong><span>게시물</span></div>${profile==='seulgi'?'<button class="ig2-stat ig2-follow-trigger" data-ig-following><strong>5</strong><span>팔로잉</span></button>':'<div class="ig2-stat"><strong>·</strong><span>프로필</span></div>'}</div><strong class="ig2-name">${esc(p.name)}</strong><p>${profile==='by'?'사진 · 기록':profile==='seulgi'?'SEULGI':'IRENE'}</p><div class="ig2-profile-actions"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Instagram ↗</a><button data-ig-view="feed">게시물 보기</button></div></section>${followingOpen&&profile==='seulgi'?following():''}<div class="ig2-grid-head"><span>▦</span><small>게시물</small></div><div class="ig2-grid">${posts.map(tile).join('')}</div></div>${bottom()}`}
  function feedCard(p,state){const key=account(p),a=person(key),pics=images(p),at=Math.min(feedSlides[p.id]||0,Math.max(0,pics.length-1)),img=pics[at],saved=state.igSaved.includes(p.id),liked=!!activity.likes[p.id],comments=(p.comment?1:0)+(activity.comments[p.id]?.length||0);return `<article class="ig2-feed-card"><header><button data-ig-profile="${key}" aria-label="${label(a)} 主页">${avatar(a)}</button><button data-ig-profile="${key}"><strong>${label(a)}</strong><small>${date(p)}</small></button><button class="ig2-more" data-ig-post="${esc(p.id)}" aria-label="帖子详情">•••</button></header><div class="ig2-feed-media ${img?'':'text'}">${img?`<button class="ig2-feed-photo" data-ig-post="${esc(p.id)}" aria-label="打开照片"><img src="${esc(photo(img))}" alt="${esc(img.alt)}" loading="lazy"></button>`:`<button data-ig-post="${esc(p.id)}" aria-label="查看帖子"><span>${esc(p.title)}</span></button>`}${pics.length>1?`<span class="ig2-feed-count">${at+1}/${pics.length}</span>${at>0?`<button class="ig2-feed-arrow prev" data-ig-feed-step="-1" data-id="${esc(p.id)}" aria-label="上一张">‹</button>`:''}${at<pics.length-1?`<button class="ig2-feed-arrow next" data-ig-feed-step="1" data-id="${esc(p.id)}" aria-label="下一张">›</button>`:''}`:''}</div>${pics.length>1?`<div class="ig2-feed-dots">${pics.slice(0,12).map((_,i)=>`<i class="${at===i?'active':''}"></i>`).join('')}${pics.length>12?'<span>…</span>':''}</div>`:''}<div class="ig2-feed-actions"><button data-ig-like="${esc(p.id)}" aria-label="${liked?'取消喜欢':'喜欢'}" aria-pressed="${liked}" class="${liked?'liked':''}">${liked?'♥':'♡'}</button><button data-ig-post="${esc(p.id)}" data-focus-comment="1" aria-label="查看评论">▢</button><button data-ig-save="${esc(p.id)}" aria-label="${saved?'取消收藏':'收藏'}" class="bookmark">${saved?'▣':'▢'}</button></div><div class="ig2-feed-copy"><strong>${label(a)}</strong> ${esc(p.caption||p.title)}${p.translation?`<small>${esc(p.translation)}</small>`:''}</div><button class="ig2-open-post" data-ig-post="${esc(p.id)}">${comments?`查看 ${comments} 条评论`:'查看帖子详情'}</button></article>`}
  function feedPage(state){return `${header('Instagram')}<div class="nf-scroll ig2-scroll"><div class="ig2-stories"><button data-ig-profile="seulgi">${avatar(D.profiles.seulgi)}<small>내 스토리</small></button><button data-ig-post="sg-meal-260916">${avatar(D.profiles.seulgi)}<small>9월 16일</small></button><button data-ig-profile="irene">${avatar(D.profiles.irene)}<small>renebaebae</small></button><button data-ig-profile="by">${avatar(by)}<small>by.sseulgi</small></button></div>${feed().map(p=>feedCard(p,state)).join('')}</div>${bottom()}`}
  function searchPage(){const q=query.trim().toLowerCase(),results=D.posts.filter(p=>!q||[p.title,p.caption,p.translation,p.account,p.date].join(' ').toLowerCase().includes(q));return `${header('검색')}<div class="nf-scroll ig2-scroll ig2-search"><form id="ig2-search-form"><span>⌕</span><input name="q" aria-label="搜索账号与帖子" placeholder="账号或帖子" value="${esc(query)}"><button aria-label="搜索">검색</button></form><div class="ig2-search-people"><button data-ig-profile="seulgi">${avatar(D.profiles.seulgi)}<span>hi_sseulgi</span></button><button data-ig-profile="irene">${avatar(D.profiles.irene)}<span>renebaebae</span></button><button data-ig-profile="by">${avatar(by)}<span>by.sseulgi</span></button></div><div class="ig2-grid">${results.map(tile).join('')}</div>${results.length?'':'<p class="ig2-empty">검색 결과가 없습니다</p>'}</div>${bottom()}`}
  function activityPage(){const liked=D.posts.filter(p=>activity.likes[p.id]),commented=D.posts.filter(p=>activity.comments[p.id]?.length);return `${header('내 활동')}<div class="nf-scroll ig2-scroll ig2-activity"><h3>좋아요</h3>${liked.length?liked.map(p=>`<button data-ig-post="${esc(p.id)}">${tilePreview(p)}<span><strong>${esc(p.account)}</strong><small>${esc(p.caption||p.title)}</small></span><b>›</b></button>`).join(''):'<p>아직 좋아요를 누른 게시물이 없습니다.</p>'}<h3>댓글</h3>${commented.length?commented.map(p=>`<button data-ig-post="${esc(p.id)}">${tilePreview(p)}<span><strong>${esc(p.account)}</strong><small>${esc(activity.comments[p.id].at(-1).text)}</small></span><b>›</b></button>`).join(''):'<p>작성한 댓글이 없습니다.</p>'}</div>${bottom()}`}
  function tilePreview(p){const img=images(p)[0];return img?`<img src="${esc(photo(img))}" alt="">`:'<span class="ig2-activity-fallback">▣</span>'}
  function postPage(state){const p=find(postId)||D.posts[0],key=account(p),a=person(key),pics=images(p),img=pics[slide],saved=state.igSaved.includes(p.id),liked=!!activity.likes[p.id],local=activity.comments[p.id]||[];return `${header('게시물',true)}<div class="nf-scroll ig2-scroll ig2-post"><header class="ig2-post-author"><button data-ig-profile="${key}">${avatar(a)}</button><button data-ig-profile="${key}"><strong>${label(a)}</strong><small>${date(p)}${p.time?' · '+esc(p.time):''}</small></button><button class="ig2-post-more" data-ig-source aria-label="查看来源">•••</button></header>${img?`<div class="ig2-stage" tabindex="0" aria-label="图片 ${slide+1}，共 ${pics.length} 张"><img src="${esc(photo(img))}" alt="${esc(img.alt)}">${pics.length>1?`<span>${slide+1}/${pics.length}</span>`:''}</div>${pics.length>1?`<div class="ig2-pager"><button data-ig-step="-1" ${slide===0?'disabled':''} aria-label="上一张">‹</button><div>${pics.map((_,i)=>`<i class="${i===slide?'active':''}"></i>`).join('')}</div><button data-ig-step="1" ${slide===pics.length-1?'disabled':''} aria-label="下一张">›</button></div>`:''}`:`<div class="ig2-stage ig2-no-photo"><span>${esc(p.title)}</span></div>`}<div class="ig2-post-body"><div class="ig2-post-actions"><button data-ig-like="${esc(p.id)}" aria-label="${liked?'取消喜欢':'喜欢'}" aria-pressed="${liked}" class="${liked?'liked':''}">${liked?'♥':'♡'}</button><button data-ig-comment-focus aria-label="写评论">▢</button><button data-ig-save="${esc(p.id)}" aria-label="${saved?'取消保存':'保存到备忘录'}" class="bookmark">${saved?'▣':'▢'}</button></div><p><strong>${label(a)}</strong> ${esc(p.caption||p.title)}</p>${p.translation?`<p class="ig2-translation">${esc(p.translation)}</p>`:''}<h3 class="ig2-comments-title">댓글 ${(p.comment?1:0)+local.length}</h3>${p.comment?`<div class="ig2-comment"><strong>${esc(p.comment.account)}</strong> ${esc(p.comment.text)}<small>${esc(p.comment.translation)}</small></div>`:''}${local.map(c=>`<div class="ig2-comment ig2-local-comment"><strong>나</strong> ${esc(c.text)}<small>${esc(c.at)}</small><button data-ig-delete-comment="${esc(c.id)}" aria-label="删除这条本地评论">×</button></div>`).join('')}<form id="ig2-comment-form"><span class="ig2-avatar ig2-self">나</span><input name="comment" maxlength="280" aria-label="添加评论" placeholder="댓글 달기..."><button>게시</button></form><time>${date(p)}</time><details class="ig2-source"><summary>출처 · 来源</summary>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Instagram 原帖 ↗</a>`:''}${p.archive?`<a href="${esc(p.archive)}" target="_blank" rel="noopener noreferrer">公开存档 ↗</a>`:''}</details></div></div>`}
  function html(state){return `<section class="nf-app ia-app ig2-app">${postId?postPage(state):view==='feed'?feedPage(state):view==='search'?searchPage():view==='activity'?activityPage():profilePage()}</section>`}
  function selectPost(id){const p=find(id);if(!p)return false;postId=id;profile=account(p);slide=feedSlides[id]||0;return true}
  function savedCards(state){const records=state.igSaved.map(find).filter(Boolean);return records.length?`<section class="ia-notebook"><small>Instagram</small>${records.map(p=>`<button class="nf-note-record" data-ig-open="${esc(p.id)}"><span>@${esc(p.account)} · ${date(p)}</span><strong>${esc(p.title)}</strong><p>${esc(p.summary)}</p></button>`).join('')}</section>`:''}
  function bind(ctx){const s=ctx.screen,redraw=ctx.render;
    s.querySelectorAll('[data-ig-profile]').forEach(b=>b.onclick=()=>{profile=b.dataset.igProfile;postId='';view='profile';followingOpen=false;slide=0;redraw()});
    s.querySelectorAll('[data-ig-view]').forEach(b=>b.onclick=()=>{view=b.dataset.igView;postId='';if(view==='profile')profile='seulgi';followingOpen=false;redraw()});
    s.querySelectorAll('[data-ig-following]').forEach(b=>b.onclick=()=>{followingOpen=!followingOpen;redraw()});
    s.querySelectorAll('[data-ig-post]').forEach(b=>b.onclick=()=>{returnView=view;selectPost(b.dataset.igPost);redraw();if(b.dataset.focusComment)s.querySelector('#ig2-comment-form input')?.focus()});
    s.querySelectorAll('[data-ig-back]').forEach(b=>b.onclick=()=>{postId='';slide=0;view=returnView;redraw()});
    s.querySelectorAll('[data-ig-save]').forEach(b=>b.onclick=()=>ctx.onSave(b.dataset.igSave));
    s.querySelectorAll('[data-ig-like]').forEach(b=>b.onclick=()=>{const id=b.dataset.igLike;activity.likes[id]=!activity.likes[id];persist();const y=s.querySelector('.nf-scroll')?.scrollTop||0;redraw();s.querySelector('.nf-scroll').scrollTop=y});
    s.querySelectorAll('[data-ig-feed-step]').forEach(b=>b.onclick=()=>{const id=b.dataset.id,p=find(id);feedSlides[id]=Math.max(0,Math.min(images(p).length-1,(feedSlides[id]||0)+Number(b.dataset.igFeedStep)));const y=s.querySelector('.nf-scroll')?.scrollTop||0;redraw();s.querySelector('.nf-scroll').scrollTop=y});
    const search=s.querySelector('#ig2-search-form');if(search)search.onsubmit=e=>{e.preventDefault();query=search.elements.q.value.trim();redraw()};
    const form=s.querySelector('#ig2-comment-form');if(form)form.onsubmit=e=>{e.preventDefault();const value=form.elements.comment.value.trim();if(!value)return;(activity.comments[postId]??=[]).push({id:Date.now().toString(36),text:value,at:new Date().toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})});persist();redraw();s.querySelector('#ig2-comment-form')?.scrollIntoView({block:'end'})};
    s.querySelectorAll('[data-ig-delete-comment]').forEach(b=>b.onclick=()=>{activity.comments[postId]=(activity.comments[postId]||[]).filter(c=>c.id!==b.dataset.igDeleteComment);persist();redraw()});
    s.querySelector('[data-ig-comment-focus]')?.addEventListener('click',()=>s.querySelector('#ig2-comment-form input')?.focus());
    s.querySelector('[data-ig-source]')?.addEventListener('click',()=>s.querySelector('.ig2-source')?.setAttribute('open',''));
    function step(n){const p=find(postId);if(!p)return;const next=Math.max(0,Math.min(images(p).length-1,slide+n));if(next===slide)return;const y=s.querySelector('.nf-scroll')?.scrollTop||0;slide=next;redraw();const sc=s.querySelector('.nf-scroll');if(sc)sc.scrollTop=y}
    s.querySelectorAll('[data-ig-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.igStep)));
    const stage=s.querySelector('.ig2-stage');if(stage){let x=0;stage.addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX},{passive:true});stage.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>45)step(dx<0?1:-1)},{passive:true});stage.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();step(e.key==='ArrowRight'?1:-1)}}}
  }
  root.InstagramArchive={html,bind,selectPost,savedCards,posts:()=>D.posts};
})(window);
